#!/usr/bin/env bash

# The GoDaddy tool's dispatcher: generated by the hosting family's scaffolder, the same for every
# provider. The provider's own hooks live in fun-godaddy.sh:
#   ensure_godaddy                              the CLI and credentials are usable, or say how
#   godaddy_do_link <project_path> <id>         link the project (writes the link file through godaddy_link_set)
#   godaddy_list_environments <id>              one environment id per line (for --select's check)
#   godaddy_do_environments <id>                print the environments for a person
#   godaddy_pull_db <project_path> <id> <env>   dump the environment's database to stdout path given in $1… (see fun-godaddy.sh)
#   godaddy_pull_files <project_path> <id> <env>
#   godaddy_do_push <project_path> <id> <env>   deploy
#   godaddy_do_logs <project_path> <id> <env>
#   godaddy_do_activities <project_path> <id>
#   godaddy_status <project_path> <id>          the closing status block

GODADDY_LINK_FILE=".godaddy/workspace.yml";

# One key of the link file, or nothing.
function godaddy_link_get() {
  local project_path="$1" key="$2";
  [ -f "${project_path}/${GODADDY_LINK_FILE}" ] || return 0 ;
  grep -E "^${key}:" "${project_path}/${GODADDY_LINK_FILE}" | head -1 | sed -E 's/^[a-z_]+:[[:space:]]*//; s/^"//; s/"$//' ;
}

# Set one key of the link file, creating it (git-excluded: it is this machine's, not the repo's).
function godaddy_link_set() {
  local project_path="$1" key="$2" value="$3" file;
  file="${project_path}/${GODADDY_LINK_FILE}";
  mkdir -p "$(dirname "${file}")" ;
  touch "${file}" ;
  if grep -qE "^${key}:" "${file}" ; then
    sed -i -E "s|^${key}:.*|${key}: ${value}|" "${file}" ;
  else
    printf '%s: %s\n' "${key}" "${value}" >> "${file}" ;
  fi
  if [ -d "${project_path}/.git" ] && ! grep -qx "/.godaddy/" "${project_path}/.git/info/exclude" 2>/dev/null ; then
    mkdir -p "${project_path}/.git/info" && printf '/.godaddy/\n' >> "${project_path}/.git/info/exclude" ;
  fi
}

function godaddy_linked_id() { godaddy_link_get "$1" id ; }
function godaddy_selected_env() { godaddy_link_get "$1" env ; }

# Which environment a run acts on: --environment for this run, else the remembered selection, else
# nothing. Deliberately NOT defaulting to production: pulling live data because nobody said
# otherwise is exactly the accident worth preventing.
function godaddy_target_env() {
  if [ ! "${ENVIRONMENT:-_none_}" == '_none_' ] ; then printf '%s' "${ENVIRONMENT}"; return 0 ; fi
  godaddy_selected_env "$1";
}

# Where this project serves from: Drupal's two conventions, plus the flat case.
function godaddy_docroot() {
  for candidate in web docroot ; do
    [ -d "$1/${candidate}" ] && { printf '%s' "${candidate}"; return 0 ; }
  done
  printf '%s' "";
}

# The local database is replaced by a pull, so it is exported first unless --no-safety-backup.
function godaddy_safety_export() {
  local project_path="$1" safety="$2";
  if [ "${NO_SAFETY_BACKUP:-no}" == 'yes' ] ; then
    echo "Skipping the local database export, as asked. The current local data will be lost.";
  else
    echo "Exporting the current local database first.";
    (cd "${project_path}" && ddev export-db --file="${safety}") \
      || echo "  (no local database to export yet — continuing)";
  fi
}

function godaddy_import_dump() {
  local project_path="$1" dump="$2";
  echo "Importing it into DDEV.";
  (cd "${project_path}" && ddev start -y > /dev/null && ddev import-db --file="${dump}") || return 1 ;
  echo "  Drupal sites usually need: ddev drush updb -y && ddev drush cr";
}

function godaddy_project_tool() {
  local project_path="${WORKSPACE_ROOT}/${doc_name}/${PROJECT_NAME}";
  local linked_id="";

  if [ ! -d "${project_path}" ]; then
    echo "No such project: ${project_path}";
    return 1 ;
  fi
  cd "${project_path}" ;
  linked_id="$(godaddy_linked_id "${project_path}")" ;

  if [ ! "${LINK:-_none_}" == '_none_' ] ; then
    ensure_godaddy || return 1 ;
    if [ -n "${linked_id}" ] && [ ! "${linked_id}" == "${LINK}" ] && [ ! "${FORCE:-no}" == 'yes' ] ; then
      echo "${doc_name}/${PROJECT_NAME} is already linked to GoDaddy ${linked_id}." ;
      echo "Re-run with --force to relink it to ${LINK}." ;
      return 1 ;
    fi
    godaddy_do_link "${project_path}" "${LINK}" || return 1 ;
    linked_id="$(godaddy_linked_id "${project_path}")" ;
    echo "Linked ${doc_name}/${PROJECT_NAME} → ${linked_id}." ;
  fi

  local needs_link="";
  for flag in "${ENVIRONMENTS:-no}" "${PULL_DB:-no}" "${PULL_FILES:-no}" "${PUSH:-no}" "${LOGS:-no}" "${ACTIVITIES:-no}" ; do
    [ "${flag}" == 'yes' ] && needs_link=yes ;
  done
  [ ! "${SELECT:-_none_}" == '_none_' ] && needs_link=yes ;
  if [ -n "${needs_link}" ] ; then
    if [ -z "${linked_id}" ] ; then
      echo "Not linked to GoDaddy — run with --link <id> first." ;
      return 1 ;
    fi
    ensure_godaddy || return 1 ;
  fi

  if [ "${ENVIRONMENTS:-no}" == 'yes' ] ; then
    godaddy_do_environments "${project_path}" "${linked_id}" || return 1 ;
    echo "";
    echo "  Select one:  bash cmd-tools-godaddy.sh ${PROJECT_NAME} --select <environment>";
  fi

  if [ ! "${SELECT:-_none_}" == '_none_' ] ; then
    # Checked against the real list rather than taken on trust: a typo would otherwise be
    # discovered by a pull that dumps the wrong environment, or none.
    if ! godaddy_list_environments "${project_path}" "${linked_id}" 2>/dev/null | grep -qx "${SELECT}" ; then
      echo "GoDaddy ${linked_id} has no environment called '${SELECT}'." ;
      echo "  List them: bash cmd-tools-godaddy.sh ${PROJECT_NAME} --environments" ;
      return 1 ;
    fi
    godaddy_link_set "${project_path}" env "${SELECT}" ;
    echo "${doc_name}/${PROJECT_NAME} now works against the ${SELECT} environment." ;
  fi

  if [ "${PULL_DB:-no}" == 'yes' ] || [ "${PULL_FILES:-no}" == 'yes' ] || [ "${PUSH:-no}" == 'yes' ] ; then
    local target_env;
    target_env="$(godaddy_target_env "${project_path}")";
    if [ -z "${target_env}" ] ; then
      echo "No environment selected. Pick one first — a pull or a deploy must never guess which environment it targets:" ;
      echo "  bash cmd-tools-godaddy.sh ${PROJECT_NAME} --environments" ;
      echo "  bash cmd-tools-godaddy.sh ${PROJECT_NAME} --select <environment>" ;
      echo "  (or name it for this run: --environment <environment>)" ;
      return 1 ;
    fi
    [ "${PULL_DB:-no}" == 'yes' ] && { godaddy_pull_db "${project_path}" "${linked_id}" "${target_env}" || return 1 ; }
    [ "${PULL_FILES:-no}" == 'yes' ] && { godaddy_pull_files "${project_path}" "${linked_id}" "${target_env}" || return 1 ; }
    [ "${PUSH:-no}" == 'yes' ] && { godaddy_do_push "${project_path}" "${linked_id}" "${target_env}" || return 1 ; }
  fi

  if [ "${LOGS:-no}" == 'yes' ] ; then
    godaddy_do_logs "${project_path}" "${linked_id}" "$(godaddy_target_env "${project_path}")" || true ;
  fi
  if [ "${ACTIVITIES:-no}" == 'yes' ] ; then
    godaddy_do_activities "${project_path}" "${linked_id}" || true ;
  fi

  # Default (and after any verb): status.
  echo "";
  echo "*---------------------------------------------------------------------*";
  echo "  ${doc_name}/${PROJECT_NAME} on GoDaddy";
  if [ -z "${linked_id}" ]; then
    echo "    not linked. Link it with:";
    echo "      bash cmd-tools-godaddy.sh ${PROJECT_NAME} --link <id>";
    godaddy_status "${project_path}" "" ;
  else
    echo "    linked:  ${linked_id}";
    local selected;
    selected="$(godaddy_selected_env "${project_path}")";
    echo "    env:     ${selected:-none selected — --environments then --select <name>}";
    godaddy_status "${project_path}" "${linked_id}" ;
  fi
  echo "*---------------------------------------------------------------------*";

  cd "${WORKSPACE_ROOT}/${doc_name}";
}
